			}
			return nil
		}); err != nil {
			return false, fmt.Errorf("reading server settings: %w", err)
		}

		if err := fr.WriteSettingsAck(); err != nil {
			return false, fmt.Errorf("writing settings ack: %w", err)
		}
		return supported, nil
	}
}

