		// intact and forwarding it to the backend.
		copyHeaderRoutes = append(copyHeaderRoutes, caddyhttp.Route{
			HandlersRaw: []json.RawMessage{caddyconfig.JSONModuleObject(
				&headers.Handler{
					Request: &headers.HeaderOps{
						Delete: []string{to},
